BODY = "# Uniform concentric Manhattan-ring interpretation; no boundary translation.\n_GEOMETRY = {}\n\ndef _geometry(h,w):\n    key=(h,w)\n    if key in _GEOMETRY:return _GEOMETRY[key]\n    all_rings=[]\n    for cy in range(h):\n        for cx in range(w):\n            shells=[0]*(h+w)\n            for y in range(h):\n                for x in range(w):shells[abs(y-cy)+abs(x-cx)] |= 1<<(y*w+x)\n            inside=0\n            for radius,shell in enumerate(shells):\n                all_rings.append((cy,cx,radius,shell,inside,tuple(shells)))\n                inside |= shell\n    _GEOMETRY[key]=all_rings\n    return all_rings\n\ndef _readings(grid):\n    h,w=len(grid),len(grid[0]);colour_masks={}\n    for y,row in enumerate(grid):\n        for x,v in enumerate(row):\n            if v!=BG:colour_masks[v]=colour_masks.get(v,0)|(1<<(y*w+x))\n    occupied=0\n    for mask in colour_masks.values():occupied |= mask\n    candidates=[];by_pixel={}\n    for cy,cx,radius,shell,inside,shells in _geometry(h,w):\n        if not shell or inside&occupied:continue\n        for colour,mask in colour_masks.items():\n            if shell&mask!=shell:continue\n            nr=radius+(-1 if colour==SHRINK else 1 if colour==GROW else 0)\n            if nr<0:continue\n            painted=shells[nr] if nr<len(shells) else 0\n            interior=0\n            for m in shells[:nr]:interior |= m\n            obj=(shell,painted,interior,colour,cy,cx,radius)\n            idx=len(candidates);candidates.append(obj)\n            bits=shell\n            while bits:\n                bit=bits&-bits;bits-=bit;by_pixel.setdefault(bit,[]).append(idx)\n    # Large objects first only changes search speed, never acceptance or ranking.\n    for choices in by_pixel.values():choices.sort(key=lambda i:-candidates[i][0].bit_count())\n    answers={};nodes=0;memo=set()\n    def visit(rem,painted,interiors,coloured,chosen):\n        nonlocal nodes\n        nodes+=1\n        if nodes>100000:raise ValueError('Exhaustive ring interpretation budget exhausted')\n        if len(answers)>1:return\n        if not rem:\n            if not 3<=len(chosen)<=6:return\n            out=[[BG]*w for _ in range(h)]\n            for colour,mask in coloured:\n                bits=mask\n                while bits:\n                    bit=bits&-bits;bits-=bit;at=bit.bit_length()-1;out[at//w][at%w]=colour\n            sig=tuple(map(tuple,out));answers.setdefault(sig,[candidates[i][4:] for i in chosen]);return\n        if len(chosen)>=6:return\n        state=(rem,painted,interiors,tuple(sorted(coloured)),len(chosen))\n        if state in memo:return\n        memo.add(state)\n        best=None;bits=rem\n        while bits:\n            bit=bits&-bits;bits-=bit;opts=[]\n            for i in by_pixel.get(bit,[]):\n                shell,new,interior,colour,*_=candidates[i]\n                if shell&rem==shell and not new&(painted|interiors) and not interior&painted:opts.append(i)\n            if not opts:return\n            if best is None or len(opts)<len(best):best=opts\n            if len(best)==1:break\n        for i in best:\n            shell,new,interior,colour,*_=candidates[i]\n            visit(rem^shell,painted|new,interiors|interior,coloured+[(colour,new)],chosen+[i])\n            if len(answers)>1:return\n    visit(occupied,0,0,[],[])\n    return answers\n\ndef solve(demonstrations,grid):\n    answers=_readings(grid)\n    if not answers:raise ValueError('No complete valid concentric-ring interpretation')\n    if len(answers)!=1:raise ValueError('Visible ring decompositions disagree on output')\n    return [list(row) for row in next(iter(answers))]\n"

def build_program(d4,palette):
    return "BG = %d\nSHRINK = %d\nGROW = %d\n" % (palette[7],palette[2],palette[5]) + BODY
